/**
 * Regression domain: none (zod error contract; not one of the 4 standing domains)
 *
 * INV-ZOD-ERROR-MAPPING-001 (TDA-B1-06): issues generated by the installed zod 4 (4.6.7; before the
 * bump, the `zod/v4` that ships inside zod 3.25.76) classify like their zod 3 counterparts. The hand-written zod 4 shaped issues in
 * inv-zod-error-mapping-001.test.ts stay as they are; this file checks that they match what zod 4
 * actually produces.
 */
import { describe, it, expect } from "vitest";
import { ZodError, type ZodIssue } from "zod";
import { z as z4 } from "zod/v4";

import { formatZodError, formatDetailedValidationError } from "../../src/utils/error-messages";

import { ECHO_SENTINEL, ZOD_ERROR_CASES } from "./support/zod-error-cases";
import {
  MAPPING_GOLDEN_PATH,
  RAWJOIN_GOLDEN_PATH,
  codeAndField,
  rawJoin,
  readGolden,
  type ConvertedIssue,
} from "./support/zod-error-golden";
import { GOLDEN_ALLOWLIST, allowedDifference, rowHasScope } from "./support/zod-golden-allowlist";

type GoldenEn = ConvertedIssue[];
const golden = readGolden(MAPPING_GOLDEN_PATH) as Record<string, { en: GoldenEn }>;

/** Run a zod/v4 schema and hand its issues to the (zod 3 class based) converter. */
function v4Error(schema: z4.ZodType, input: unknown): ZodError {
  const r = schema.safeParse(input);
  if (r.success) throw new Error("case unexpectedly parsed successfully");
  return new ZodError(r.error.issues as unknown as ZodIssue[]);
}

const UUID = "0190a0a0-0000-7000-8000-000000000000";

interface V4Case {
  /** case id in the 4a golden (taken on zod 3.x) */
  id: string;
  err: () => ZodError;
}

/**
 * Golden cases with no zod/v4 case here, and why. Empty today: every golden case has a zod 4
 * counterpart. V4_CASES plus these must equal the golden keys.
 */
const V4_EXCLUDED: Readonly<Record<string, string>> = {};

/** The case table of the 4a golden, run on the installed zod (one table: TDA-B2B-06). */
const V4_CASES: V4Case[] = ZOD_ERROR_CASES.map((c) => ({ id: c.id, err: c.run }));

describe("INV-ZOD-ERROR-MAPPING-001 real zod 4 issues (installed 4.6.7)", () => {
  it("the installed zod 4 really produces zod 4 shaped issues (no received, renamed codes)", () => {
    const missing = v4Error(z4.object({ query: z4.string() }), {});
    expect(missing.issues[0]).not.toHaveProperty("received");
    const uuid = v4Error(z4.object({ id: z4.string().uuid() }), { id: UUID + "x" });
    expect(uuid.issues[0]?.code).toBe("invalid_format");
    const mode = v4Error(z4.object({ mode: z4.enum(["a"]) }), { mode: "b" });
    expect(mode.issues[0]?.code).toBe("invalid_value");
    const small = v4Error(z4.object({ n: z4.number().min(1) }), { n: 0 });
    expect(small.issues[0]).toHaveProperty("origin", "number");
  });

  // Expected value per row comes from the allowlist (support/zod-golden-allowlist.ts): no row ->
  // equal to the zod 3 golden; kind "message" -> same code + field; kind "code" -> the pinned expected.
  for (const c of V4_CASES) {
    it(`classifies like the zod 3 golden or its allowlist row: ${c.id}`, () => {
      const expected = golden[c.id]?.en;
      expect(expected).toBeDefined();
      const actual = formatZodError(c.err());
      const row = allowedDifference(c.id, "4a", 4);
      if (row?.kind === "code") {
        expect(codeAndField(actual)).toEqual(row.expected);
      } else if (row?.kind === "message") {
        expect(codeAndField(actual)).toEqual(codeAndField(expected ?? []));
      } else {
        expect(actual).toEqual(expected);
      }
    });
  }

  it("real zod/v4 date / bigint / set size issues keep UNKNOWN_ERROR (converted) and OUT_OF_RANGE (detailed)", () => {
    const errs = [
      v4Error(z4.object({ at: z4.date().min(new Date("2026-01-01T00:00:00.000Z")) }), {
        at: new Date("2025-01-01T00:00:00.000Z"),
      }),
      v4Error(z4.object({ n: z4.bigint().min(5n) }), { n: 1n }),
      v4Error(z4.object({ s: z4.set(z4.string()).min(2) }), { s: new Set(["a"]) }),
    ];
    for (const err of errs) {
      expect(formatZodError(err).map((e) => e.code)).toEqual(["UNKNOWN_ERROR"]);
      expect(formatDetailedValidationError(err).errors.map((e) => e.code)).toEqual([
        "OUT_OF_RANGE",
      ]);
    }
  });

  it("zod 4 enum / union / literal / discriminated union do not echo the input value", () => {
    const errs = [
      v4Error(z4.object({ mode: z4.enum(["fast", "slow"]) }), { mode: ECHO_SENTINEL }),
      v4Error(z4.object({ v: z4.union([z4.string(), z4.number()]) }), {
        v: { k: ECHO_SENTINEL },
      }),
      v4Error(z4.object({ v: z4.literal("on") }), { v: ECHO_SENTINEL }),
      v4Error(
        z4.object({
          v: z4.discriminatedUnion("kind", [
            z4.object({ kind: z4.literal("a") }),
            z4.object({ kind: z4.literal("b") }),
          ]),
        }),
        { v: { kind: ECHO_SENTINEL } }
      ),
    ];
    for (const err of errs) {
      const out = JSON.stringify({
        a: formatZodError(err),
        b: formatDetailedValidationError(err),
      });
      expect(out).not.toContain(ECHO_SENTINEL);
    }
  });

  it("zod 4 unrecognized key keeps the code of the zod 3 golden (key name echo is the pinned known gap)", () => {
    const err = v4Error(z4.strictObject({ a: z4.string() }), { a: "x", [ECHO_SENTINEL]: 1 });
    expect(formatZodError(err).map((e) => e.code)).toEqual(
      (golden["strict-unrecognized-key-sentinel"]?.en ?? []).map((e) => e.code)
    );
  });
});

describe("INV-ZOD-ERROR-MAPPING-001 coverage and the allowlist are closed sets", () => {
  it("V4_CASES plus the reasoned exclusions are exactly the golden keys", () => {
    expect(Object.values(V4_EXCLUDED).every((r) => r.length > 0)).toBe(true);
    expect([...V4_CASES.map((c) => c.id), ...Object.keys(V4_EXCLUDED)].sort()).toEqual(
      Object.keys(golden).sort()
    );
  });

  it("the cases where real zod 4 differs from the zod 3 golden (4a) are exactly the rows with scope 4a", () => {
    const differing = V4_CASES.filter(
      (c) => JSON.stringify(formatZodError(c.err())) !== JSON.stringify(golden[c.id]?.en)
    )
      .map((c) => c.id)
      .sort();
    expect(differing).toEqual(
      GOLDEN_ALLOWLIST.filter((r) => rowHasScope(r, "4a"))
        .map((r) => r.id)
        .sort()
    );
  });

  it("every kind code row really differs from the golden in code or field (no over-classification)", () => {
    for (const r of GOLDEN_ALLOWLIST.filter((x) => x.kind === "code")) {
      expect(r.expected).not.toEqual(codeAndField(golden[r.id]?.en ?? []));
    }
  });

  it("every allowlist row names a golden case and a reason; code rows pin the zod 4 result", () => {
    for (const r of GOLDEN_ALLOWLIST) {
      expect(golden[r.id]).toBeDefined();
      expect(r.reason.length).toBeGreaterThan(0);
      if (r.kind === "code") expect(r.expected?.length ?? 0).toBeGreaterThan(0);
      else expect(r.expected).toBeUndefined();
    }
  });

  it("the allowlist is inactive on zod 3 and active from zod 4", () => {
    expect(allowedDifference("enum-invalid-number", "4a", 3)).toBeUndefined();
    expect(allowedDifference("enum-invalid-number", "4a", 4)?.kind).toBe("code");
    expect(allowedDifference("required-missing", "4a", 4)).toBeUndefined();
  });
});

/** Measured against the installed zod 4 (TPA-B2B-01; first measured on the zod/v4 bundled in 3.25.76). */
describe("INV-ZOD-ERROR-RAWJOIN-SNAPSHOT-001 (4b) the installed zod 4 against the raw-join snapshot", () => {
  const snapshot = readGolden(RAWJOIN_GOLDEN_PATH);
  const rawOf = (c: V4Case): unknown => {
    const issues = c.err().issues;
    return { joined: rawJoin(issues), messages: issues.map((e) => e.message) };
  };
  const differing = V4_CASES.filter(
    (c) => JSON.stringify(rawOf(c)) !== JSON.stringify(snapshot[c.id])
  ).map((c) => c.id);

  // The original 42 cases measured 38 differing / 4 identical (TPA-B2B-01); the bigint and set size
  // cases added in B2c-2 differ too, so 40 of the 44 now. Measured again on zod 4.6.7: instanceof now
  // differs and discriminated-union-no-match-sentinel no longer does.
  it("40 of the 44 cases change their raw default message; 4 stay identical", () => {
    expect(V4_CASES).toHaveLength(44);
    expect(differing).toHaveLength(40);
    expect(
      V4_CASES.map((c) => c.id)
        .filter((id) => !differing.includes(id))
        .sort()
    ).toEqual([
      "custom-refine",
      "custom-refine-default-message",
      "discriminated-union-no-match-sentinel",
      "union-no-match-sentinel",
    ]);
  });

  it("the differing cases are exactly the rows with scope 4b", () => {
    expect([...differing].sort()).toEqual(
      GOLDEN_ALLOWLIST.filter((r) => rowHasScope(r, "4b"))
        .map((r) => r.id)
        .sort()
    );
  });

  it("the 4a / 4b split is 19 rows in both (10 + the bigint and set size rows + the 7 OUT_OF_RANGE reword rows) and 21 rows in 4b only", () => {
    expect(GOLDEN_ALLOWLIST.filter((r) => r.scope === "both")).toHaveLength(19);
    expect(GOLDEN_ALLOWLIST.filter((r) => r.scope === "4b")).toHaveLength(21);
    expect(GOLDEN_ALLOWLIST.filter((r) => r.scope === "4a")).toHaveLength(0);
  });

  it("a 4b-only row is skipped by the 4b comparison and not by the 4a comparison", () => {
    expect(allowedDifference("required-missing", "4b", 4)?.scope).toBe("4b");
    expect(allowedDifference("required-missing", "4a", 4)).toBeUndefined();
    expect(allowedDifference("enum-invalid-number", "4a", 4)?.scope).toBe("both");
    expect(allowedDifference("enum-invalid-number", "4b", 3)).toBeUndefined();
  });
});
